        shadow = {
            enabled        = true,
            range          = 18,
            render_power   = 4,
            color          = { colors = {"rgba(8f008faa)", "rgba(008f8faa)", "rgba(8f8f00aa)"}, angle = 45 },
            color_inactive = 0x00000000,
        },


        blur = {
            enabled   = true,
            size      = 3,
            passes    = 1,
