hl.animation({ leaf = "workspacesOut", enabled = true,  speed = 2.5, bezier = "easeOutQuint", style = "slidefade 20%" })

hl.animation({ leaf = "zoomFactor",    enabled = true,  speed = 7,    bezier = "quick" })

