---- KEYBINDINGS ----
---------------------

local mainMod = "SUPER"

hl.bind(mainMod .. " + C", hl.dsp.exec_cmd(terminal))
local closeWindowBind = hl.bind(mainMod .. " + Q", hl.dsp.window.close())

hl.bind(mainMod .. " + End", hl.dsp.exec_cmd("command -v hyprshutdown >/dev/null 2>&1 && hyprshutdown || hyprctl dispatch 'hl.dsp.exit()'")) -- Decide on this

hl.bind(mainMod .. " + E", hl.dsp.exec_cmd(fileManager))
-- hl.bind(mainMod .. " + V", hl.dsp.window.float({ action = "toggle" }))
hl.bind(mainMod .. " + V", function()
  local w = hl.get_active_window()
  if w == nil then return end

  if w.floating then
    hl.dispatch(hl.dsp.window.float({ action = "unset", window = w }))
  else
    hl.dispatch(hl.dsp.window.float({ action = "set", window = w }))
    hl.dispatch(hl.dsp.window.resize({ x = 1600, y = 1280, window = w }))
    hl.dispatch(hl.dsp.window.center({ window = w }))
  end
end)

hl.bind(mainMod .. " + W", hl.dsp.exec_cmd(menu))
hl.bind(mainMod .. " + SHIFT + W", hl.dsp.exec_cmd("cliphist list | fuzzel --dmenu | cliphist decode | wl-copy"))

hl.bind(mainMod .. " + B", hl.dsp.exec_cmd(browser))

hl.bind(mainMod .. " + M", hl.dsp.exec_cmd(messenger))

hl.bind(mainMod .. " + Delete", hl.dsp.exec_cmd("systemctl hibernate"))

-- hl.bind(mainMod .. " + P", hl.dsp.window.pseudo()) -- Useless (?)

hl.bind(mainMod .. " + O", hl.dsp.layout("togglesplit"))    -- dwindle only

hl.bind(mainMod .. " + Escape", hl.dsp.exec_cmd("hyprlock"))    -- dwindle only

hl.bind(mainMod .. " + semicolon", hl.dsp.exec_cmd("hyprshot -m output -m DP-1"))
hl.bind(mainMod .. " + SHIFT + semicolon", hl.dsp.exec_cmd(fileManager .. " /home/sage/Screenshots"))

hl.bind(mainMod .. " + apostrophe", hl.dsp.exec_cmd("hyprshot -m output -m region -z"))
hl.bind(mainMod .. " + SHIFT + apostrophe", hl.dsp.exec_cmd("hyprshot -m window -m active"))

hl.bind(mainMod .. " + F", hl.dsp.window.fullscreen({ action = "toggle", mode = "fullscreen", layout_aware = "false" }))


-- Move focus with mainMod + arrow keys
hl.bind(mainMod .. " + H",  hl.dsp.focus({ direction = "left" }))
hl.bind(mainMod .. " + L", hl.dsp.focus({ direction = "right" }))
hl.bind(mainMod .. " + K",    hl.dsp.focus({ direction = "up" }))
hl.bind(mainMod .. " + J",  hl.dsp.focus({ direction = "down" }))

hl.bind(mainMod .. " + Home", hl.dsp.exec_cmd("killall waybar && waybar"))

-- Switch workspaces with mainMod + [0-9]
-- Move active window to a workspace with mainMod + SHIFT + [0-9]
for i = 1, 10 do
    local key = i % 10 -- 10 maps to key 0
    hl.bind(mainMod .. " + " .. key,             hl.dsp.focus({ workspace = i}))
    hl.bind(mainMod .. " + SHIFT + " .. key,     hl.dsp.window.move({ workspace = i }))
end

-- Example special workspace (scratchpad)
hl.bind(mainMod .. " + S",         hl.dsp.workspace.toggle_special("magic"))
hl.bind(mainMod .. " + SHIFT + S", hl.dsp.window.move({ workspace = "special:magic" }))

-- Move/resize windows with mainMod + LMB/RMB and dragging
hl.bind(mainMod .. " + mouse:272", hl.dsp.window.drag(),   { mouse = true })
hl.bind(mainMod .. " + mouse:273", hl.dsp.window.resize(), { mouse = true })

hl.bind(mainMod .. " + SHIFT + H", hl.dsp.window.move({ direction = "l" }))
hl.bind(mainMod .. " + SHIFT + L", hl.dsp.window.move({ direction = "r" }))
hl.bind(mainMod .. " + SHIFT + K", hl.dsp.window.move({ direction = "u" }))
hl.bind(mainMod .. " + SHIFT + J", hl.dsp.window.move({ direction = "d" }))

hl.bind(mainMod .. " + SHIFT + C", hl.dsp.window.center())

hl.bind(mainMod .. " + ALT + H", hl.dsp.window.resize({ x = -50, y = 0,    relative = true }), { repeating = true })
hl.bind(mainMod .. " + ALT + L", hl.dsp.window.resize({ x =  50, y = 0,    relative = true }), { repeating = true })
hl.bind(mainMod .. " + ALT + K", hl.dsp.window.resize({ x = 0,    y = -50, relative = true }), { repeating = true })
hl.bind(mainMod .. " + ALT + J", hl.dsp.window.resize({ x = 0,    y = 50,  relative = true }), { repeating = true })

hl.bind(mainMod .. " + SHIFT + ALT + H", hl.dsp.window.resize({ x = -950, y = 0,    relative = true }), { repeating = true })
hl.bind(mainMod .. " + SHIFT + ALT + L", hl.dsp.window.resize({ x =  950, y = 0,    relative = true }), { repeating = true })
hl.bind(mainMod .. " + SHIFT + ALT + K", hl.dsp.window.resize({ x = 0,    y = -950, relative = true }), { repeating = true })
hl.bind(mainMod .. " + SHIFT + ALT + J", hl.dsp.window.resize({ x = 0,    y = 950,  relative = true }), { repeating = true })

-- Cycle focus
hl.bind(mainMod .. " + SHIFT + TAB", hl.dsp.window.cycle_next())
hl.bind(mainMod .. " + TAB",         hl.dsp.window.cycle_next({ next = false }))

-- Cycle through floating windows
hl.bind(mainMod .. " + SHIFT + O", hl.dsp.window.cycle_next({ floating = true }))
hl.bind(mainMod .. " + SHIFT + N", hl.dsp.window.cycle_next({ next = false, floating = true }))

